CREATE TABLE IF NOT EXISTS ssh_events (id bigint AUTO_INCREMENT PRIMARY KEY, event_id varchar(36) NOT NULL, server_id varchar(36) NOT NULL, event_type varchar(32) NOT NULL, username varchar(128) NOT NULL, source_ip varchar(45) NOT NULL, source_port integer, auth_method varchar(32) NOT NULL DEFAULT '', outcome varchar(16) NOT NULL, occurred_at datetime(6) NOT NULL, received_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), UNIQUE KEY events_unique(server_id,event_id), FOREIGN KEY(server_id) REFERENCES servers(id), INDEX events_time(occurred_at), INDEX events_server_time(server_id,occurred_at), INDEX events_ip_time(source_ip,occurred_at), CHECK(event_type IN ('ssh.login','ssh.login_failed')), CHECK(source_port BETWEEN 1 AND 65535), CHECK(outcome IN ('success','failure'))) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
